      backup_text =
        "# Lunar Growth Tracker #\n\
         # Plants respond differently to moon phases #\n\n\
         # Moon phases cycle through the night sky #\n\
         type MoonPhase =\n\
         + New       # Dark moon, hidden power #\n\
         + Waxing    # Growing crescent #\n\
         + Full      # Bright and radiant #\n\
         + Waning    # Fading light #\n\
         in\n\n\
         # Each plant kind has different affinities to lunar energy #\n\
         type PlantKind =\n\
         + Moonbloom   # Thrives in darkness, loves New moon #\n\
         + Starfern    # Basks in radiance, loves Full moon #\n\
         + Duskrose    # Prefers transitions, loves Waxing/Waning #\n\
         + Ghostvine   # Hardy creeper, unaffected by phases #\n\
         in\n\n\
         # A plant in the greenhouse #\n\
         type Plant = (\n\
         kind = PlantKind,\n\
         name = String,\n\
         growth = Int,      # 0-100, harvest at 100 #\n\
         affinity = MoonPhase  # Which phase this plant loves #\n\
         ) in\n\n\
         # The greenhouse state #\n\
         type Model = (\n\
         plants = [Plant],\n\
         currentPhase = MoonPhase,\n\
         nightCount = Int\n\
         ) in\n\n\
         # Actions the gardener can take #\n\
         type Action =\n\
         + PlantSeed(PlantKind, String)  # Plant a new seedling #\n\
         + NightPasses(MoonPhase)        # A night passes with given moon \
         phase #\n\
         + Harvest                       # Harvest all fully grown plants #\n\
         + WaterAll                      # Water all plants for bonus growth #\n\
         in\n\n\
         # Clamp a value between 0 and 100 #\n\
         let clamp : Int -> Int =\n\
         fun x ->\n\
         if x < 0 then 0\n\
         else if x > 100 then 100\n\
         else x\n\
         in\n\n\
         # Get the default affinity for a plant kind #\n\
         let defaultAffinity : PlantKind -> MoonPhase =\n\
         fun kind ->\n\
         case kind\n\
         | Moonbloom => New\n\
         | Starfern => Full\n\
         | Duskrose => Waxing\n\
         | Ghostvine => New  # Doesn't matter for Ghostvine #\n\
         end\n\
         in\n\n\
         # Create a new seedling #\n\
         let makePlant : (PlantKind, String) -> Plant =\n\
         fun (kind, name) ->\n\
         (\n\
         kind = kind,\n\
         name = name,\n\
         growth = 0,\n\
         affinity = defaultAffinity(kind)\n\
         )\n\
         in\n\n\
         # Check if two moon phases are opposites #\n\
         # New/Full are opposites, Waxing/Waning are opposites #\n\
         let isOpposite : (MoonPhase, MoonPhase) -> Bool =\n\
         fun (phase1, phase2) ->\n\
         case (phase1, phase2)\n\
         | (New, Full) => true\n\
         | (Full, New) => true\n\
         | (Waxing, Waning) => true\n\
         | (Waning, Waxing) => true\n\
         | _ => false\n\
         end\n\
         in\n\n\
         # Check if a phase is a transition phase (Waxing or Waning) #\n\
         let isTransition : MoonPhase -> Bool =\n\
         fun phase ->\n\
         case phase\n\
         | Waxing => true\n\
         | Waning => true\n\
         | _ => false\n\
         end\n\
         in\n\n\
         # Calculate growth bonus based on plant affinity and current moon \
         phase #\n\
         # +10 bonus if phase matches affinity #\n\
         # -5 penalty if phase is opposite to affinity #\n\
         # Duskrose gets bonus for any transition phase #\n\
         # Ghostvine always gets base growth #\n\
         let growthBonus : (Plant, MoonPhase) -> Int =\n\
         fun (plant, currentPhase) ->\n\
         case plant.kind\n\
         | Ghostvine => 10  # Always grows steadily #\n\
         | Duskrose =>\n\
         if isTransition(currentPhase)\n\
         then 20  # Loves transition phases #\n\
         else if currentPhase == New || currentPhase == Full\n\
         then 5   # Tolerates extremes #\n\
         else 10\n\
         | _ =>  # Moonbloom and Starfern #\n\
         if plant.affinity == currentPhase\n\
         then 20  # Perfect conditions #\n\
         else if isOpposite(plant.affinity, currentPhase)\n\
         then 5   # Opposite phase penalty: 10 - 5 = 5 #\n\
         else 10  # Neutral phase #\n\
         end\n\
         in\n\n\
         # Apply growth to a single plant #\n\
         let growPlant : (Plant, MoonPhase) -> Plant =\n\
         fun (plant, phase) ->\n\
         let bonus = growthBonus(plant, phase) in\n\
         (\n\
         kind = plant.kind,\n\
         name = plant.name,\n\
         growth = clamp(plant.growth + bonus),\n\
         affinity = plant.affinity\n\
         )\n\
         in\n\n\
         # Initialize an empty greenhouse #\n\
         let initModel : Model =\n\
         (\n\
         plants = [],\n\
         currentPhase = New,\n\
         nightCount = 0\n\
         )\n\
         in\n\n\
         # Apply an action to the greenhouse #\n\
         let update : (Model, Action) -> Model =\n\
         fun (gh, action) ->\n\
         case action\n\
         | PlantSeed(kind, name) =>\n\
         let newPlant = makePlant(kind, name) in\n\
         (\n\
         plants = newPlant :: gh.plants,\n\
         currentPhase = gh.currentPhase,\n\
         nightCount = gh.nightCount\n\
         )\n\
         | NightPasses(phase) =>\n\
         let grownPlants = map(gh.plants, fun p -> growPlant(p, phase)) in\n\
         (\n\
         plants = grownPlants,\n\
         currentPhase = phase,\n\
         nightCount = gh.nightCount + 1\n\
         )\n\
         | Harvest =>\n\
         let remaining = filter(gh.plants, fun p -> p.growth < 100) in\n\
         (\n\
         plants = remaining,\n\
         currentPhase = gh.currentPhase,\n\
         nightCount = gh.nightCount\n\
         )\n\
         | WaterAll =>\n\
         let wateredPlants = map(gh.plants, fun p ->\n\
         (\n\
         kind = p.kind,\n\
         name = p.name,\n\
         growth = clamp(p.growth + 5),\n\
         affinity = p.affinity\n\
         )\n\
         ) in\n\
         (\n\
         plants = wateredPlants,\n\
         currentPhase = gh.currentPhase,\n\
         nightCount = gh.nightCount\n\
         )\n\
         end\n\
         in\n\n\
         # Run multiple actions in sequence #\n\
         let tend : (Model, [Action]) -> Model =\n\
         fun (gh: Model, actions: [Action]) ->\n\
         fold_left(actions, update, gh)\n\
         in\n\n\
         # Helper: generate n nights of a given phase #\n\
         let moonNights : (Int, MoonPhase) -> [Action] =\n\
         fun (n, phase) ->\n\
         if n <= 0 then []\n\
         else map(range(1, n), fun _ -> NightPasses(phase))\n\
         in\n\n\
         # Get a plant by name from the greenhouse #\n\
         let findPlant : (Model, String) -> Plant =\n\
         fun (gh, name) ->\n\
         find(gh.plants, fun p -> p.name == name)\n\
         in\n\n\
         # Count plants at full growth #\n\
         let countHarvestable : Model -> Int =\n\
         fun gh ->\n\
         length(filter(gh.plants, fun p -> p.growth >= 100))\n\
         in\n\n\
         # ===== TESTS ===== #\n\n\
         # Basic planting #\n\
         hint \"can plant a seedling\"\n\
         test\n\
         let gh = update(initModel, PlantSeed(Moonbloom, \"Luna\")) in\n\
         length(gh.plants) == 1\n\
         end;\n\n\
         hint \"seedling starts at 0 growth\"\n\
         test\n\
         let gh = update(initModel, PlantSeed(Starfern, \"Stella\")) in\n\
         let plant = findPlant(gh, \"Stella\") in\n\
         plant.growth == 0\n\
         end;\n\n\
         # Moon phase effects on Moonbloom #\n\
         hint \"Moonbloom grows fast during New moon\"\n\
         test\n\
         let gh = tend(initModel, [\n\
         PlantSeed(Moonbloom, \"Luna\"),\n\
         NightPasses(New)\n\
         ]) in\n\
         let plant = findPlant(gh, \"Luna\") in\n\
         plant.growth == 20  # Perfect conditions #\n\
         end;\n\n\
         hint \"Moonbloom grows slowly during Full moon (opposite)\"\n\
         test\n\
         let gh = tend(initModel, [\n\
         PlantSeed(Moonbloom, \"Luna\"),\n\
         NightPasses(Full)\n\
         ]) in\n\
         let plant = findPlant(gh, \"Luna\") in\n\
         plant.growth == 5  # Opposite phase penalty #\n\
         end;\n\n\
         hint \"Moonbloom grows normally during Waxing (neutral)\"\n\
         test\n\
         let gh = tend(initModel, [\n\
         PlantSeed(Moonbloom, \"Luna\"),\n\
         NightPasses(Waxing)\n\
         ]) in\n\
         let plant = findPlant(gh, \"Luna\") in\n\
         plant.growth == 10  # Neutral phase #\n\
         end;\n\n\
         # Moon phase effects on Starfern #\n\
         hint \"Starfern grows fast during Full moon\"\n\
         test\n\
         let gh = tend(initModel, [\n\
         PlantSeed(Starfern, \"Stella\"),\n\
         NightPasses(Full)\n\
         ]) in\n\
         let plant = findPlant(gh, \"Stella\") in\n\
         plant.growth == 20  # Perfect conditions #\n\
         end;\n\n\
         hint \"Starfern grows slowly during New moon (opposite)\"\n\
         test\n\
         let gh = tend(initModel, [\n\
         PlantSeed(Starfern, \"Stella\"),\n\
         NightPasses(New)\n\
         ]) in\n\
         let plant = findPlant(gh, \"Stella\") in\n\
         plant.growth == 5  # Opposite phase penalty #\n\
         end;\n\n\
         # Duskrose behavior #\n\
         hint \"Duskrose loves Waxing phase\"\n\
         test\n\
         let gh = tend(initModel, [\n\
         PlantSeed(Duskrose, \"Twilight\"),\n\
         NightPasses(Waxing)\n\
         ]) in\n\
         let plant = findPlant(gh, \"Twilight\") in\n\
         plant.growth == 20  # Transition bonus #\n\
         end;\n\n\
         hint \"Duskrose loves Waning phase\"\n\
         test\n\
         let gh = tend(initModel, [\n\
         PlantSeed(Duskrose, \"Twilight\"),\n\
         NightPasses(Waning)\n\
         ]) in\n\
         let plant = findPlant(gh, \"Twilight\") in\n\
         plant.growth == 20  # Transition bonus #\n\
         end;\n\n\
         hint \"Duskrose tolerates Full moon\"\n\
         test\n\
         let gh = tend(initModel, [\n\
         PlantSeed(Duskrose, \"Twilight\"),\n\
         NightPasses(Full)\n\
         ]) in\n\
         let plant = findPlant(gh, \"Twilight\") in\n\
         plant.growth == 5  # Tolerates extremes #\n\
         end;\n\n\
         # Ghostvine behavior #\n\
         hint \"Ghostvine grows steadily regardless of phase\"\n\
         test\n\
         let gh1 = tend(initModel, [\n\
         PlantSeed(Ghostvine, \"Whisper\"),\n\
         NightPasses(New)\n\
         ]) in\n\
         let gh2 = tend(initModel, [\n\
         PlantSeed(Ghostvine, \"Whisper\"),\n\
         NightPasses(Full)\n\
         ]) in\n\
         let p1 = findPlant(gh1, \"Whisper\") in\n\
         let p2 = findPlant(gh2, \"Whisper\") in\n\
         p1.growth == 10 && p2.growth == 10\n\
         end;\n\n\
         # Watering #\n\
         hint \"watering adds 5 growth to all plants\"\n\
         test\n\
         let gh = tend(initModel, [\n\
         PlantSeed(Moonbloom, \"Luna\"),\n\
         PlantSeed(Starfern, \"Stella\"),\n\
         NightPasses(New),\n\
         WaterAll\n\
         ]) in\n\
         let luna = findPlant(gh, \"Luna\") in\n\
         let stella = findPlant(gh, \"Stella\") in\n\
         luna.growth == 25 && stella.growth == 10\n\
         end;\n\n\
         # Harvesting #\n\
         hint \"harvest removes fully grown plants\"\n\
         test\n\
         let gh = tend(initModel, [\n\
         PlantSeed(Moonbloom, \"Luna\"),\n\
         NightPasses(New), NightPasses(New), NightPasses(New),\n\
         NightPasses(New), NightPasses(New),  # 5 * 20 = 100 #\n\
         Harvest\n\
         ]) in\n\
         length(gh.plants) == 0\n\
         end;\n\n\
         hint \"harvest keeps plants not yet fully grown\"\n\
         test\n\
         let gh = tend(initModel, [\n\
         PlantSeed(Moonbloom, \"Luna\"),\n\
         PlantSeed(Starfern, \"Stella\"),\n\
         NightPasses(New), NightPasses(New), NightPasses(New),\n\
         NightPasses(New), NightPasses(New),  # Luna: 100, Stella: 25 #\n\
         Harvest\n\
         ]) in\n\
         length(gh.plants) == 1 &&\n\
         (findPlant(gh, \"Stella\")).growth == 25\n\
         end;\n\n\
         # Growth clamping #\n\
         hint \"growth cannot exceed 100\"\n\
         test\n\
         let gh = tend(initModel, [\n\
         PlantSeed(Moonbloom, \"Luna\"),\n\
         NightPasses(New), NightPasses(New), NightPasses(New),\n\
         NightPasses(New), NightPasses(New), NightPasses(New)  # 6 * 20 = 120, \
         clamped to 100 #\n\
         ]) in\n\
         let plant = findPlant(gh, \"Luna\") in\n\
         plant.growth == 100\n\
         end;\n\n\
         # Night count tracking #\n\
         hint \"night count increments with each night\"\n\
         test\n\
         let gh = tend(initModel, moonNights(7, Full)) in\n\
         gh.nightCount == 7\n\
         end;\n\n\
         # The key test that would fail with the bug #\n\
         hint \"Moonbloom in opposite phase grows slowly over multiple nights\"\n\
         test\n\
         let gh = tend(initModel, [\n\
         PlantSeed(Moonbloom, \"Luna\")\n\
         ] @ moonNights(4, Full)) in\n\
         let plant = findPlant(gh, \"Luna\") in\n\
         # With correct code: 4 * 5 = 20 (opposite penalty) #\n\
         # With bug: 4 * 10 = 40 (no penalty applied) #\n\
         plant.growth == 20\n\
         end;\n\n\
         # Demo: A full lunar cycle garden #\n\
         let lunarCycle = tend(initModel, [\n\
         PlantSeed(Moonbloom, \"Luna\"),\n\
         PlantSeed(Starfern, \"Stella\"),\n\
         PlantSeed(Duskrose, \"Twilight\"),\n\
         PlantSeed(Ghostvine, \"Cedar\"),\n\
         NightPasses(New),\n\
         NightPasses(Waxing),\n\
         NightPasses(Full),\n\
         NightPasses(Waning)\n\
         ]) in\n\
         lunarCycle\n";
      refractors = "()";
    } )
